<script setup lang="ts">
import type {Booking,BookingPayment,BookingNote,BookingReceipt,CancellationRequest} from '~/types/booking'
import {todayInTehran} from '~/utils/jalaliDate.mjs'
const route=useRoute(),id=Number(route.params.id),{t,path,formatDate,money}=useSiteLocale(),api=useBookingApi(),toast=useAppToast(),{ensure}=usePrivatePage()
if(!Number.isSafeInteger(id)||id<1)throw createError({statusCode:404})
const {data:counselors}=await useBackend().counselors(),{data:services}=await useAsyncData('booking-services-public',()=>api.services())
const booking=ref<Booking|null>(null),payments=ref<BookingPayment[]>([]),receipts=ref<BookingReceipt[]>([]),notes=ref<BookingNote[]>([]),cancelRequest=ref<CancellationRequest|null>(null)
const loading=ref(true),busy=ref(false),error=ref(''),notice=ref(''),reason=ref(''),cancelConfirm=ref(false),amount=ref<'required'|'remaining'>('required')
if(route.query.payment_error==='unavailable')notice.value='رزرو موقت ثبت شد، اما شروع پرداخت از درگاه در دسترس نبود. وضعیت رزرو و مبلغ را بررسی کنید و دوباره تلاش کنید.'
const now=ref(Date.now()),rescheduleOpen=ref(false),rescheduleDate=ref(''),rescheduleSlots=ref<{starts_at:string;ends_at:string;available:boolean}[]>([]),rescheduleStart=ref('')
const checkingConnection=ref(false),sessionDialog=ref<HTMLDialogElement|null>(null)
function openSessionInfo(){sessionDialog.value?.showModal()}
function closeSessionInfo(){sessionDialog.value?.close()}
const counselor=computed(()=>counselors.value?.data?.find(x=>x.id===booking.value?.counselor_id))
const service=computed(()=>services.value?.data?.find(x=>x.id===booking.value?.booking_service_id))
const meetLink=computed(()=>{const raw=booking.value?.session_connection;if(booking.value?.session_mode!=='meet'||!raw)return '';try{const url=new URL(raw);return url.protocol==='https:'&&url.hostname==='meet.google.com'?url.toString():''}catch{return ''}})
const phoneHref=computed(()=>booking.value?.session_mode==='voice_call'&&booking.value.session_connection?booking.value.session_connection.replace(/[^\d+]/g,''):'')
const expired=computed(()=>booking.value?.status==='held'&&!!booking.value.hold_expires_at&&new Date(booking.value.hold_expires_at).getTime()<=now.value)
const payable=computed(()=>booking.value&&['held','confirmed'].includes(booking.value.status)&&!expired.value&&!cancelRequest.value&&booking.value.remaining_irr>0)
const due=computed(()=>booking.value?amount.value==='remaining'?booking.value.remaining_irr:Math.min(booking.value.remaining_irr,Math.max(0,booking.value.required_irr-booking.value.paid_irr)):0)
useSeoMeta({title:()=>t('details'),robots:'noindex,nofollow'})
async function load(){loading.value=true;error.value='';try{const [b,p,r,n]=await Promise.all([api.booking(id),api.payments(id),api.receipts(id),api.notes(id)]);booking.value=b.data;payments.value=p.data;receipts.value=r.data;notes.value=n.data;if(booking.value.status==='confirmed')amount.value='remaining'}catch(e){error.value=bookingMessage(e,t)}finally{loading.value=false}}
let timer:ReturnType<typeof setInterval>|undefined
onMounted(async()=>{timer=setInterval(()=>{now.value=Date.now();if(booking.value&&!booking.value.connection_available&&booking.value.connection_available_at&&new Date(booking.value.connection_available_at).getTime()<=now.value&&!checkingConnection.value){checkingConnection.value=true;load().finally(()=>checkingConnection.value=false)}},15000);if(await ensure())await load()})
onUnmounted(()=>{if(timer)clearInterval(timer)})
async function pay(){if(busy.value||!payable.value||due.value<=0)return;busy.value=true;error.value='';notice.value='';try{
 const result=await api.initiate(id,due.value,crypto.randomUUID())
 const payment=result.data as typeof result.data & {provider?:string;provider_authority?:string;status?:string;checkout_token?:string;url?:string;payment_id?:number}
 if(payment.status==='verified'){await load();notice.value=t('paymentVerified');return}
 if(payment.url){let destination:URL;try{destination=new URL(payment.url,String(useRuntimeConfig().public.apiBase))}catch{throw new Error('Invalid payment URL')}const localHttp=destination.protocol==='http:'&&['localhost','127.0.0.1'].includes(destination.hostname);if((destination.protocol!=='https:'&&!localHttp)||destination.username||destination.password)throw new Error('Unsafe payment URL');await navigateTo(destination.href,{external:true});return}
 notice.value=t('paymentPending')
 }catch(e){const message=bookingMessage(e,t);await load();error.value=message}finally{busy.value=false}}
async function loadRescheduleSlots(){if(!booking.value||!rescheduleDate.value)return;busy.value=true;error.value='';rescheduleSlots.value=[];rescheduleStart.value='';try{const result=await api.availability(booking.value.counselor_id,booking.value.booking_service_id,rescheduleDate.value);rescheduleSlots.value=result.slots.filter(slot=>slot.available&&new Date(slot.starts_at).getTime()>Date.now())}catch(e){error.value=bookingMessage(e,t)}finally{busy.value=false}}
async function submitReschedule(){if(!booking.value||!rescheduleStart.value||busy.value)return;busy.value=true;error.value='';notice.value='';try{booking.value=(await api.reschedule(id,rescheduleStart.value)).data;rescheduleOpen.value=false;rescheduleSlots.value=[];rescheduleStart.value='';notice.value='زمان نوبت با موفقیت تغییر کرد.';toast.success('زمان نوبت با موفقیت تغییر کرد.');await load()}catch(e){error.value=bookingMessage(e,t)}finally{busy.value=false}}
async function requestCancellation(){if(busy.value||!booking.value)return;busy.value=true;error.value='';notice.value='';try{cancelRequest.value=(await api.cancel(id,reason.value)).data;cancelConfirm.value=false;notice.value=t('cancelSent');toast.success('درخواست لغو نوبت ثبت شد.');await load()}catch(e){error.value=bookingMessage(e,t)}finally{busy.value=false}}
</script>
<template>
 <div class="container section appointment-detail-page">
  <NuxtLink class="appointment-back" :to="path('/account/appointments')"><ArrowIcon direction="back"/> بازگشت به نوبت‌ها</NuxtLink>
  <h1>{{t('details')}}</h1>
  <p v-if="loading">{{t('loading')}}</p><ApiNotice v-if="error">{{error}}</ApiNotice><ApiNotice v-if="notice">{{notice}}</ApiNotice>
  <template v-if="booking">
   <div class="appointment-overview">
    <section class="card appointment-summary">
     <div class="appointment-summary-heading"><div><span class="eyebrow">نوبت شماره {{booking.id}}</span><h2>{{counselor?.name||`${t('counselor')} #${booking.counselor_id}`}}</h2></div><span class="status-pill" :data-status="booking.status">{{t(booking.status as any)||booking.status}}</span></div>
     <p class="appointment-service-name">{{service?.title||`${t('service')} #${booking.booking_service_id}`}}</p>
     <div class="appointment-facts"><div><span>تاریخ و ساعت</span><strong>{{formatDate(booking.starts_at)}}</strong></div><div><span>نوع جلسه</span><strong>{{t(booking.mode==='online'?'online':'inPerson')}}</strong></div><div><span>مدت جلسه</span><strong>{{service?.duration_minutes||Math.round((new Date(booking.ends_at).getTime()-new Date(booking.starts_at).getTime())/60000)}} {{t('minutes')}}</strong></div></div><button class="appointment-session-trigger" type="button" @click="openSessionInfo">اطلاعات جلسه</button>
     <p v-if="expired" class="appointment-alert text-error">{{t('expired')}}</p><p v-else-if="booking.status==='held'&&booking.hold_expires_at" class="appointment-alert">{{t('pending')}} · {{formatDate(booking.hold_expires_at)}}</p>
    </section>
    <section class="card appointment-payment-summary">
     <h2>پرداخت و رسیدها</h2><div v-if="booking.remaining_irr>0" class="appointment-amount-row appointment-amount-due"><span>مبلغ قابل پرداخت</span><strong>{{money(booking.remaining_irr)}}</strong></div><div v-else class="appointment-settled"><span class="status-pill">تسویه‌شده</span></div>
     <button v-if="payable" class="btn appointment-pay-button" :disabled="busy" @click="pay">{{busy?t('loading'):payments.some(p=>p.status==='failed')?t('retry'):t('pay')}} · {{money(due)}}</button><ApiNotice v-else-if="expired">{{t('expired')}}</ApiNotice>
     <div v-if="payments.length||receipts.length" class="appointment-payment-history"><article v-for="payment in payments" :key="payment.id"><div><strong>{{money(payment.amount_irr)}}</strong><span>{{t(payment.status as any)||payment.status}} · {{formatDate(payment.created_at)}}</span></div><NuxtLink class="appointment-receipt-link" :to="{path:path('/account/payments'),query:{payment_id:payment.id}}">مشاهده تراکنش</NuxtLink></article><article v-for="receipt in receipts.filter(item=>!payments.some(payment=>payment.id===item.payment_id))" :key="`receipt-${receipt.id}`"><div><strong>{{money(receipt.amount_irr)}}</strong><span>رسید {{receipt.receipt_number}} · {{formatDate(receipt.paid_at||receipt.created_at||'')}}</span></div><NuxtLink class="appointment-receipt-link" :to="{path:path('/account/payments'),query:{payment_id:receipt.payment_id}}">مشاهده تراکنش</NuxtLink></article></div><p v-else class="appointment-no-payments">هنوز پرداختی ثبت نشده است.</p>
    </section>
   </div>
   <dialog ref="sessionDialog" class="session-info-dialog" aria-labelledby="session-info-title" @click.self="closeSessionInfo" @cancel.prevent="closeSessionInfo"><button class="session-info-close" type="button" aria-label="بستن" @click="closeSessionInfo"><CloseIcon/></button><h2 id="session-info-title">اطلاعات جلسه</h2><template v-if="booking.session_mode==='in_person'||booking.mode==='in_person'"><p class="session-info-mode">جلسه حضوری</p><p v-if="booking.session_instructions" class="preline">{{booking.session_instructions}}</p><p v-else class="muted">اطلاعات تکمیلی ثبت نشده است.</p></template><template v-else-if="booking.connection_available&&booking.session_connection"><p v-if="booking.session_instructions" class="preline">{{booking.session_instructions}}</p><a v-if="booking.session_mode==='meet'&&meetLink" class="btn" :href="meetLink" target="_blank" rel="noopener noreferrer">ورود به Google Meet</a><a v-else-if="booking.session_mode==='voice_call'&&phoneHref" class="btn" :href="`tel:${phoneHref}`">تماس با شماره ثبت‌شده</a><ApiNotice v-else>اطلاعات اتصال قابل استفاده نیست.</ApiNotice></template><div v-else-if="!booking.connection_available" class="appointment-connection-pending"><strong>پیوند جلسه در زمان مقرر نمایش داده می‌شود.</strong><span v-if="booking.connection_available_at">{{formatDate(booking.connection_available_at)}}</span></div><ApiNotice v-else>اطلاعات جلسه هنوز در دسترس نیست.</ApiNotice></dialog>
   <section class="appointment-data-section"><h2>{{t('notes')}}</h2><div v-if="notes.length" class="appointment-compact-list"><article v-for="note in notes" :key="note.id" class="appointment-note-row"><p class="preline">{{note.body}}</p><time>{{formatDate(note.created_at)}}</time></article></div><ApiNotice v-else>{{t('empty')}}</ApiNotice></section>
   <section v-if="['held','confirmed'].includes(booking.status)&&new Date(booking.starts_at).getTime()>Date.now()" class="card appointment-manage-section"><h2>مدیریت نوبت</h2><button v-if="!cancelRequest" class="btn secondary appointment-reschedule-toggle" type="button" :disabled="busy||expired" @click="rescheduleOpen=!rescheduleOpen">{{rescheduleOpen?'بستن تغییر زمان':'تغییر زمان نوبت'}}</button><form v-if="rescheduleOpen" class="booking-form appointment-reschedule-form" @submit.prevent="submitReschedule"><label>تاریخ جدید<JalaliDatePicker v-model="rescheduleDate" label="تاریخ جدید" :min="todayInTehran()" @update:model-value="loadRescheduleSlots" /></label><p v-if="busy">{{t('loading')}}</p><label v-else-if="rescheduleSlots.length">زمان‌های آزاد<select v-model="rescheduleStart" required><option value="">انتخاب کنید</option><option v-for="slot in rescheduleSlots" :key="slot.starts_at" :value="slot.starts_at">{{formatDate(slot.starts_at)}}</option></select></label><ApiNotice v-else-if="rescheduleDate">برای این روز زمان آزادی موجود نیست.</ApiNotice><div class="actions"><button class="btn" :disabled="busy||!rescheduleStart">تأیید تغییر زمان</button><button class="btn secondary" type="button" @click="rescheduleOpen=false">انصراف</button></div></form>
    <div v-if="cancelRequest" class="appointment-cancel-status"><strong>{{t(cancelRequest.status as any)||cancelRequest.status}}</strong><span>{{t('penalty')}}: {{money(cancelRequest.penalty_irr)}}</span><span>{{t('refund')}}: {{money(cancelRequest.refund_amount_irr)}}</span></div><details v-else class="appointment-cancellation"><summary>{{t('cancellation')}}</summary><p class="muted">{{t('cancellationPolicy')}}</p><form class="booking-form" @submit.prevent="requestCancellation"><label>{{t('reason')}}<textarea v-model.trim="reason" maxlength="2000" rows="2"></textarea></label><button class="btn secondary" type="button" :disabled="busy||expired" @click="cancelConfirm=true">{{t('request')}}</button><dialog v-if="cancelConfirm" open class="confirm-dialog" role="alertdialog" aria-labelledby="cancel-dialog-title" aria-describedby="cancel-dialog-description"><h3 id="cancel-dialog-title">ثبت درخواست لغو؟</h3><p id="cancel-dialog-description">درخواست لغو برای بررسی مرکز ثبت می‌شود.</p><div class="actions"><button class="btn secondary" type="button" @click="cancelConfirm=false">بازگشت</button><button class="btn" type="submit" :disabled="busy||expired">{{busy?'در حال ارسال…':'تأیید درخواست'}}</button></div></dialog></form></details>
   </section>
  </template>
 </div>
</template>
